package main
package main

import (
	"fmt"
	"log"
	"os"
	"syscall"

	tea "github.com/charmbracelet/bubbletea"
	"linkthings.io/client/config"
	"linkthings.io/client/keymgmt"
	"linkthings.io/client/ui"
)

// Version is set during build
var Version = "1.0.0"

func main() {
	// Check for admin privileges on Windows
	if !isAdmin() {
		fmt.Println("Error: This application requires administrator privileges.")
		fmt.Println("Please run as administrator.")
		os.Exit(1)
	}

	// Initialize configuration manager
	configMgr, err := config.NewConfigManager()
	if err != nil {
		log.Fatalf("Failed to initialize config manager: %v", err)
	}

	// Load or create configuration
	if err := configMgr.Load(); err != nil {
		log.Fatalf("Failed to load configuration: %v", err)
	}

	// Initialize key manager
	keyMgr, err := keymgmt.NewKeyManager()
	if err != nil {
		log.Fatalf("Failed to initialize key manager: %v", err)
	}

	// Ensure SSH keys exist (generate if first run)
	if err := keyMgr.EnsureKeys(); err != nil {
		log.Fatalf("Failed to ensure SSH keys: %v", err)
	}

	// Create TUI model
	mainModel := ui.NewMainModel(configMgr)

	// Start TUI application
	if err := runTUI(mainModel); err != nil {
		log.Fatalf("TUI error: %v", err)
	}
}

// runTUI starts the Bubble Tea TUI application
func runTUI(model tea.Model) error {
	p := tea.NewProgram(model, tea.WithAltScreen(), tea.WithMouseCellMotion())

	_, err := p.Run()
	return err
}

// isAdmin checks if the current process has administrator privileges on Windows
func isAdmin() bool {
	_, err := os.Open("\\\\.\\PHYSICALDRIVE0")
	if err != nil {
		return false
	}
	return true

	// Alternative check using Windows API
	// This is a simplified check; more robust version would use Windows API directly
	// _, err := os.Open("\\\\?\\UNC\\localhost\\c$")
	// return err == nil
}

// Alternative: More robust admin check using Windows API
func isAdminRobust() bool {
	// This uses Windows API to check admin privileges
	// For now, using a simpler method above
	verb := "runas"
	exe, _ := os.Executable()
	cwd, _ := os.Getwd()
	args := os.Args[1:]

	verbPtr, _ := syscall.UTF16PtrFromString(verb)
	exePtr, _ := syscall.UTF16PtrFromString(exe)
	cwdPtr, _ := syscall.UTF16PtrFromString(cwd)
	argsStr := ""
	for _, arg := range args {
		argsStr += arg + " "
	}
	argsPtr, _ := syscall.UTF16PtrFromString(argsStr)

	showCmd := int32(1) // SW_NORMAL

	err := syscall.ShellExecute(0, verbPtr, exePtr, argsPtr, cwdPtr, showCmd)
	return err == 0
}
